-- Hand-written: Full audit M6–M7 fix round AF3: the clean-up's measured rows written are a whole number that only goes up, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `retention_run_counts_written_insert` BEFORE INSERT ON `retention_run_counts` WHEN typeof(NEW.written) <> 'integer' OR NEW.written < 0 BEGIN SELECT RAISE(ABORT, 'retention_run_counts_written_insert: a clean-up count has a whole number of rows written, never below 0'); END;
