CREATE TRIGGER `retention_run_counts_written_update` BEFORE UPDATE OF written ON `retention_run_counts` WHEN typeof(NEW.written) <> 'integer' OR NEW.written < 0 OR NEW.written < OLD.written BEGIN SELECT RAISE(ABORT, 'retention_run_counts_written_update: a clean-up count has a whole number of rows written that only goes up'); END;
